/* @lc app=leetcode id=2841 lang=kotlin */ class Solution { fun maxSum(nums: List<Int>, m: Int, k: Int): Long = nums.indices.fold(Triple(mutableMapOf<Int, Int>(), 0L, 0L)) { (map, sum, max), i -> (sum + nums[i].toLong()).let { s1 -> map.apply { put(nums[i], (get(nums[i]) ?: 0) + 1) }.run { if (i >= k) (s1 - nums[i - k].toLong()).also { map.put(nums[i - k], map[nums[i - k]]!! - 1) }.also { if (map[nums[i - k]] == 0) map.remove(nums[i - k]) } else s1 }.let { s2 -> Triple(map, s2, if (i >= k - 1 && map.size >= m) maxOf(max, s2) else max) } } }.third }